export const TEST_AUDIO_BASE64 = "";

export function decodeTestAudio(): ArrayBuffer {
  const bin = atob(TEST_AUDIO_BASE64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

